import json

def factorize(n):
    factors = {}
    d = 2
    m = n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

n = 33146799
f = factorize(n)

# verify product
prod = 1
