# verify primality of each factor by trial division
def is_prime(x):
    if x < 2:
        return False
    i = 2
    while i * i <= x:
        if x % i == 0:
            return False
        i += 1
    return True

if prod == n and all(is_prime(p) for p in f):
    primes = sorted(f)
    expr = " * ".join(f"{p}^{e}" if e > 1 else str(p) for p, e in sorted(f.items()))
    print(json.dumps({
        "final_answer": ", ".join(map(str, primes)),
        "evidence": {
            "n": n,
            "factorization": expr,
            "multiplicities": {str(p): e for p, e in sorted(f.items())},
            "product_check": prod == n
        }
    }))
else:
